"""Join original Native sources for the two approach phases; no legal verdict."""
import hashlib
import json
import math
from pathlib import Path
import subprocess

AID='training__C405647__NRS-484B-267-2f__motor_vehicle_driver'
CAMERAS=('overview','approach','reference_corner','driver_reference')
COUNT=600


def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def rows(p):return [json.loads(x) for x in Path(p).read_text().splitlines() if x.strip()]
def finite(x):return type(x) in (int,float) and math.isfinite(x)


def measure(root):
    root=Path(root)
    names=('video_frames.jsonl','vehicle_poses.jsonl','emergency_context.json')
    sources={n:root/n for n in names}
    if any(not p.is_file() for p in sources.values()):raise ValueError('Original frame, pose and reviewed context sources required')
    frames,poses=rows(sources[names[0]]),rows(sources[names[1]])
    c=json.loads(sources[names[2]].read_text())
    if len(frames)!=COUNT or len(poses)!=COUNT or c.get('assignment_id')!=AID:
        raise ValueError('Exact assignment and 600 source frames required')
    kind=c.get('review_kind')
    if kind not in ('synthetic_diagnostic','original_source_review'):raise ValueError('Source provenance review required')
    for k in ('reviewer','ego_driver_source','emergency_authorization_source',
              'qualifying_flash_equipment_source','flashing_light_visual_source',
              'lane_boundary_source','visibility_review_source','officer_direction_review_source'):
        if not c.get(k):raise ValueError('Missing statutory source: '+k)
    if c.get('emergency_vehicle_authorized') is not True or c.get('qualifying_flash_equipment_reviewed') is not True:
        raise ValueError('Emergency authorization or qualifying lights unproved')
    if type(c.get('officer_directed_otherwise')) is not bool:
        raise ValueError('Officer direction exception unreviewed')
    if type(c.get('ego_actor_id')) is not int or type(c.get('emergency_actor_id')) is not int or c['ego_actor_id']==c['emergency_actor_id']:
        raise ValueError('Distinct actor identities required')
    cam_hashes={}
    if kind=='original_source_review':
        for name in CAMERAS:
            p=root/(name+'.mkv')
            if not p.is_file():raise ValueError('Original camera missing: '+name)
            q=subprocess.run(['ffprobe','-v','error','-count_frames','-select_streams','v:0',
                              '-show_entries','stream=nb_read_frames,r_frame_rate','-of','json',str(p)],capture_output=True,text=True)
            if q.returncode:raise ValueError('Original camera decode failed: '+name)
            streams=json.loads(q.stdout).get('streams',[])
            if len(streams)!=1 or streams[0].get('nb_read_frames')!='600' or streams[0].get('r_frame_rate')!='20/1':
                raise ValueError('Original 600-frame camera source missing: '+name)
            cam_hashes[p.name]=sha(p)
        if c.get('camera_sha256')!=cam_hashes:raise ValueError('Camera source hash differs')
    prev_n=-1;prev_t=-1.0;distances=[];ego_speeds=[];em_speeds=[];light=[];derived=[]
    for i,(f,p) in enumerate(zip(frames,poses)):
        n,t=f.get('native_frame'),f.get('time_s')
        if f.get('video_frame')!=i or type(n) is not int or n<=prev_n or not finite(t) or t<=prev_t or (i and abs(t-prev_t-.05)>.005):
            raise ValueError('Original frame/time join failed')
        if p.get('video_frame')!=i or p.get('native_frame')!=n or p.get('source_kind')!=('synthetic_native_sample' if kind=='synthetic_diagnostic' else 'original_native_pose'):
            raise ValueError('Original pose provenance differs')
        e,m=p.get('ego'),p.get('emergency')
        if not isinstance(e,dict) or not isinstance(m,dict) or e.get('actor_id')!=c['ego_actor_id'] or m.get('actor_id')!=c['emergency_actor_id']:
            raise ValueError('Actor identity join failed')
        for v in (e,m):
            if any(not finite(v.get(k)) for k in ('x_m','y_m','heading_rad','velocity_x_mps','velocity_y_mps','speed_mps','half_length_m','half_width_m')):
                raise ValueError('Original vehicle pose/velocity/extent missing')
            if v['speed_mps']<0 or v['half_length_m']<=0 or v['half_width_m']<=0:
                raise ValueError('Original vehicle motion or extent invalid')
        if type(m.get('special1_light_on')) is not bool:raise ValueError('Original emergency light state missing')
        d=math.hypot(e['x_m']-m['x_m'],e['y_m']-m['y_m'])
        distances.append(d);ego_speeds.append(e['speed_mps']);em_speeds.append(m['speed_mps']);light.append(m['special1_light_on'])
        derived.append({'video_frame':i,'native_frame':n,'time_s':t,'separation_m':d,
                        'ego_x_m':e['x_m'],'ego_y_m':e['y_m'],
                        'ego_half_length_m':e['half_length_m'],
                        'ego_half_width_m':e['half_width_m'],
                        'emergency_x_m':m['x_m'],
                        'emergency_half_length_m':m['half_length_m'],
                        'ego_speed_mps':e['speed_mps'],'emergency_speed_mps':m['speed_mps'],
                        'emergency_velocity_x_mps':m['velocity_x_mps'],'heading_dot':math.cos(e['heading_rad']-m['heading_rad']),
                        'light_state_special1':m['special1_light_on']})
        prev_n,prev_t=n,t
    if frames[-1]['time_s']-frames[0]['time_s']<29.9:raise ValueError('Full 30-second observation required')
    if not distances[80]<distances[0]:raise ValueError('Initial subject approach not measured')
    if max(em_speeds[:80])>0.15 or not min(x['emergency_velocity_x_mps'] for x in derived[120:220])<-.5:
        raise ValueError('Subsequent emergency approach not measured')
    if not distances[220]<distances[120]:raise ValueError('Subsequent closing relationship not measured')
    if not all(x['heading_dot']<-.8 for x in derived[:220]):raise ValueError('Opposing distinct routes not measured')
    if set(light)!={True,False}:raise ValueError('Flashing light state changes not measured')
    suffix=c.get('case_id','').rsplit('__',1)[-1]
    if suffix != 'officer_direction':
        raise ValueError('Exact response case missing')
    passed_frames=[x['video_frame'] for x in derived[120:] if
                   x['emergency_x_m']+x['emergency_half_length_m'] <
                   x['ego_x_m']-x['ego_half_length_m']]
    first_pass=passed_frames[0] if passed_frames else None
    if suffix=='controlled_1':
        if first_pass is None or first_pass<220:
            raise ValueError('Approaching emergency pass not measured after right-edge stop')
        if (derived[100]['ego_y_m']<=derived[119]['ego_y_m'] or
            any(abs(x['ego_y_m']+2.5)>.15 or abs(x['ego_speed_mps'])>.15
                for x in derived[120:first_pass])):
            raise ValueError('Right-edge position and stop-until-passed response not measured')
        if not all(x['ego_y_m']-x['ego_half_width_m']>=-3.65 for x in derived[120:first_pass]):
            raise ValueError('Right-edge body extends beyond authored road')
    elif any(x['ego_speed_mps']<2.5 or abs(x['ego_y_m']+1.75)>.15 for x in derived[120:220]):
        raise ValueError('Continued-travel comparison response not measured')
    from measure_officer import measure as measure_direction
    direction=measure_direction(root)
    return {'format':'source-bound-two-phase-emergency-approach-v1','assignment_id':AID,
            'source_sha256':{**{k:sha(v) for k,v in sources.items()},**cam_hashes},
            'samples':COUNT,'initial_subject_approach_m':distances[0]-distances[80],
            'subsequent_emergency_approach_m':distances[120]-distances[220],
            'ego_speed_before_mps':sum(ego_speeds[20:80])/60,
            'ego_speed_after_mps':sum(ego_speeds[160:220])/60,
            'right_edge_stop_until_passed_observed':suffix=='controlled_1',
            'officer_direction_indicator':direction,
            'emergency_pass_frame':first_pass,
            'light_phase_changes':sum(a!=b for a,b in zip(light,light[1:])),
            'per_frame_geometry':derived,'subsection_1_duty_resolved':False,'legal_result':None,
            'physical_acceptance_claimed':False}

"""Request a visible walker arm pose for a source driver or directing officer.

CARLA's unified walker skeleton provides shoulder, arm, forearm and hand bones.
The returned request is not evidence that a driver saw or understood the pose.
"""


def request_bones(carla, side='R'):
    if side not in ('L', 'R'):
        raise ValueError('Select one modeled hand')
    # Parent-relative rotations follow CARLA's WalkerBoneControl contract.
    poses = ((f'crl_shoulder__{side}', (0, 0, -45 if side == 'R' else 45)),
             (f'crl_arm__{side}', (0, 0, -55 if side == 'R' else 55)),
             (f'crl_foreArm__{side}', (0, 0, -35 if side == 'R' else 35)),
             (f'crl_hand__{side}', (0, 90, 0)))
    return [(name, carla.Transform(rotation=carla.Rotation(pitch=pitch, yaw=yaw, roll=roll)))
            for name, (pitch, yaw, roll) in poses]


def apply_hand_signal(carla, walker, side='R'):
    """Submit and read back a custom arm pose; fail if Native lacks the API."""
    transforms = request_bones(carla, side)
    if hasattr(walker, 'set_bones') and hasattr(carla, 'WalkerBoneControlIn'):
        walker.set_bones(carla.WalkerBoneControlIn(transforms))
        if not hasattr(walker, 'show_pose'):
            raise ValueError('Native walker pose blending unavailable')
        walker.show_pose()
    elif hasattr(walker, 'apply_control') and hasattr(carla, 'WalkerBoneControl'):
        control = carla.WalkerBoneControl()
        control.bone_transforms = transforms
        walker.apply_control(control)
    else:
        raise ValueError('Native walker bone-control API unavailable')
    if not hasattr(walker, 'get_bones'):
        raise ValueError('Native walker bone readback unavailable')
    readback = walker.get_bones()
    names = {row.name if hasattr(row, 'name') else row[0] for row in readback.bone_transforms}
    requested = {name for name, _ in transforms}
    if not requested <= names:
        raise ValueError('Native hand-signal bones absent in readback')
    return {'requested_bones': sorted(requested), 'readback_bones': sorted(requested),
            'visual_visibility_verified': False}


def spawn_source_driver_proxy(carla, world, source_vehicle, blueprint_id,
                              offset_m=(0.0, -1.5, 0.0)):
    """Create a visible walker proxy beside the source vehicle for Native review.

    The proxy is an acquisition aid. Original camera review must establish that
    viewers understand it as the source driver and can see its hand signal.
    """
    if not blueprint_id.startswith('walker.pedestrian.'):
        raise ValueError('Source driver proxy must use a walker skeleton')
    vehicle_pose = source_vehicle.get_transform()
    location = vehicle_pose.location
    spawn = carla.Transform(
        carla.Location(x=location.x + offset_m[0],
                       y=location.y + offset_m[1],
                       z=location.z + offset_m[2]),
        carla.Rotation(yaw=vehicle_pose.rotation.yaw))
    walker = world.try_spawn_actor(world.get_blueprint_library().find(blueprint_id), spawn)
    if walker is None:
        raise RuntimeError('Reviewed source driver proxy spawn failed')
    return walker

"""Source-bound officer direction exception measurement; no legal verdict."""
import hashlib
import json
import math
from pathlib import Path


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines()]


def measure(root):
    root = Path(root)
    names = ('video_frames.jsonl', 'vehicle_poses.jsonl',
             'officer_track.jsonl', 'officer_direction.json')
    if any(not (root / name).is_file() for name in names):
        raise ValueError('Original frame, pose, officer track and direction review required')
    frames, poses, track = (rows(root / name) for name in names[:3])
    review = json.loads((root / names[3]).read_text())
    if len(frames) != 600 or len(poses) != 600 or len(track) != 600:
        raise ValueError('Full 600-frame officer source join required')
    if review.get('review_kind') not in ('synthetic_diagnostic', 'original_source_review'):
        raise ValueError('Officer source provenance required')
    for field in ('reviewer', 'law_enforcement_identity_source',
                  'direction_visual_source', 'direction_to_subject_source'):
        if not review.get(field):
            raise ValueError('Officer identity or visible direction source missing: ' + field)
    if review.get('directed_otherwise') is not True or review.get('directive') != 'continue_travel':
        raise ValueError('Exact otherwise-directed response is unreviewed')
    if type(review.get('officer_actor_id')) is not int or type(review.get('ego_actor_id')) is not int:
        raise ValueError('Distinct officer and driver actor IDs required')
    if review['officer_actor_id'] == review['ego_actor_id']:
        raise ValueError('Officer and driver actor identities overlap')
    for name in names[:3]:
        if review.get('source_sha256', {}).get(name) != sha(root / name):
            raise ValueError('Officer source hash differs: ' + name)
    if review['review_kind'] == 'original_source_review':
        for camera in ('overview', 'approach', 'reference_corner', 'driver_reference'):
            name = camera + '.mkv'
            if not (root / name).is_file() or review.get('camera_sha256', {}).get(name) != sha(root / name):
                raise ValueError('Original officer camera source missing or changed: ' + name)
    observed = []
    previous_native = -1
    previous_time = -1.0
    for index, (frame, pose, officer) in enumerate(zip(frames, poses, track)):
        native, time = frame.get('native_frame'), frame.get('time_s')
        if (frame.get('video_frame') != index or pose.get('video_frame') != index or
                officer.get('video_frame') != index or type(native) is not int or
                native <= previous_native or pose.get('native_frame') != native or
                officer.get('native_frame') != native or type(time) not in (int, float) or
                not math.isfinite(time) or time <= previous_time or
                (index and abs(time - previous_time - .05) > .005)):
            raise ValueError('Original officer/frame/pose time join differs')
        ego = pose.get('ego', {})
        if ego.get('actor_id') != review['ego_actor_id'] or officer.get('actor_id') != review['officer_actor_id']:
            raise ValueError('Officer or driver identity differs')
        for field in ('x_m', 'y_m'):
            if (type(officer.get(field)) not in (int, float) or not math.isfinite(officer[field]) or
                    type(ego.get(field)) not in (int, float) or not math.isfinite(ego[field])):
                raise ValueError('Officer or driver position missing')
        if math.hypot(officer['x_m'] - ego['x_m'], officer['y_m'] - ego['y_m']) > 80:
            raise ValueError('Officer is outside requested driver scene')
        if type(officer.get('direction_active')) is not bool:
            raise ValueError('Original officer direction state missing')
        if officer['direction_active']:
            bones = officer.get('pose_bones_requested')
            if not isinstance(bones, list) or 'crl_hand__R' not in bones:
                raise ValueError('Officer direction pose request missing')
            observed.append(index)
        previous_native, previous_time = native, time
    if not observed or min(observed) > 120 or max(observed) < 180:
        raise ValueError('Officer direction interval is not present during approach')
    return {'case_id': review['case_id'], 'directive': review['directive'],
            'direction_start_frame': min(observed), 'direction_end_frame': max(observed),
            'source_sha256': {name: sha(root / name) for name in names},
            'visual_direction_verified': False,
            'original_review_declared': review['review_kind'] == 'original_source_review',
            'legal_verdict': None, 'physical_acceptance_claimed': False}
